const keyboardActivate=action=>event=>{if(event.target===event.currentTarget&&(event.key==='Enter'||event.key===' ')){event.preventDefault();action()}}
class AppErrorBoundary extends React.Component{
 constructor(props){super(props);this.state={error:null}}
 static getDerivedStateFromError(error){return{error}}
 componentDidCatch(error,info){
   console.error('Autologika renderer error',error,info)
   api?.diagnosticsLog?.write?.({type:'react',message:String(error?.message||error),stack:String(error?.stack||''),componentStack:String(info?.componentStack||'')}).catch?.(()=>{})
 }
 render(){
   if(this.state.error)return <div className="fatalScreen"><div className="fatalCard"><div className="brandMark">A</div><h1>Autologika OS napotkała błąd widoku</h1><p>Zamiast czarnego ekranu aplikacja zatrzymała tylko uszkodzony widok. Możesz bezpiecznie przeładować interfejs.</p><code>{String(this.state.error?.message||this.state.error)}</code><div className="actionrow"><button className="primary" onClick={()=>window.location.reload()}>↻ Przeładuj aplikację</button><button onClick={()=>this.setState({error:null})}>Spróbuj wrócić</button></div></div></div>
   return this.props.children
 }
}
window.addEventListener('error',e=>{api?.diagnosticsLog?.write?.({type:'window-error',message:String(e.message||''),stack:String(e.error?.stack||''),source:e.filename||'',line:e.lineno||0}).catch?.(()=>{})})
window.addEventListener('unhandledrejection',e=>{api?.diagnosticsLog?.write?.({type:'unhandled-rejection',message:String(e.reason?.message||e.reason||''),stack:String(e.reason?.stack||'')}).catch?.(()=>{})})

function AppVersion(){const[version,setVersion]=useState('—');useEffect(()=>{api.updater.getStatus().then(x=>setVersion(x.currentVersion||'—'))},[]);return <>Autologika OS · {version}</>}
function BootSplash(){return <div className="bootSplash" role="status" aria-label="Uruchamianie Autologika OS"><div className="bootGlow"/><img src="./brand/autologika-logo.png" alt="AutoLogika — Mechanika, Diagnostyka, Rozwój"/><div className="bootProgress"><i/></div><span>URUCHAMIANIE SYSTEMU WARSZTATOWEGO</span></div>}
function FeedbackToast({notice,close}){const duration=notice.tone==='error'?8000:4500;return <div className={'appFeedbackToast '+(notice.tone||'success')} style={{'--feedback-duration':`${duration}ms`}} role={notice.tone==='error'?'alert':'status'} aria-live={notice.tone==='error'?'assertive':'polite'}><span aria-hidden="true">{notice.tone==='error'?'!':notice.tone==='warning'?'△':'✓'}</span><div><b>{notice.title}</b>{notice.detail&&<small>{notice.detail}</small>}</div><button type="button" aria-label="Zamknij komunikat" onClick={close}>×</button><i className="appFeedbackProgress" aria-hidden="true"/></div>}
function Deferred({children}){return <React.Suspense fallback={<Loading/>}>{children}</React.Suspense>}

function App(){
 const[booting,setBooting]=useState(true);const[page,setPage]=useState('dashboard');const[refresh,setRefresh]=useState(0);const[syncPulse,setSyncPulse]=useState(0);const[selectedOrderId,setSelectedOrderId]=useState(null);const[customerTarget,setCustomerTarget]=useState(null);const[vehicleTarget,setVehicleTarget]=useState(null);const[paletteOpen,setPaletteOpen]=useState(false);const[remoteNotice,setRemoteNotice]=useState(null);const[globalScanNotice,setGlobalScanNotice]=useState('');const[manualContext,setManualContext]=useState(null);const[intakeScan,setIntakeScan]=useState(null);const[partScan,setPartScan]=useState(null);const[attentionCount,setAttentionCount]=useState(0);const[showDeliveryImport,setShowDeliveryImport]=useState(false);const[appNotices,setAppNotices]=useState([]),appNotice=appNotices[0]||null;const[navExpanded,setNavExpanded]=useState(()=>localStorage.getItem('autologika.navExpanded')==='1');const[outdoorMode,setOutdoorMode]=useState(()=>localStorage.getItem('autologika.outdoorMode')==='1')
 const openOrder=id=>{setSelectedOrderId(Number(id)||id);setPage('center');setPaletteOpen(false)}
 const openCustomer=id=>{setCustomerTarget({id:Number(id)||id,nonce:Date.now()});setVehicleTarget(null);setPage('customers');setPaletteOpen(false)}
 const openVehicle=id=>{setVehicleTarget({id:Number(id)||id,nonce:Date.now()});setCustomerTarget(null);setPage('customers');setPaletteOpen(false)}
 const openIntakeFromScan=useCallback(scan=>{setIntakeScan({...scan,nonce:Date.now()});setPage('intake');setPaletteOpen(false)},[])
 const openDeliveryImport=useCallback(()=>{setShowDeliveryImport(true);setPaletteOpen(false)},[])
 const handleGlobalScan=useCallback(async raw=>{if(isProductBarcode(raw)){const barcode=normalizeProductBarcode(raw),scan={...analyzeScan(raw),kind:'KOD PRODUKTU',barcode};api.zebra?.recordCapture?.(scan).catch(()=>{});setGlobalScanNotice('');const event=new CustomEvent('autologika:product-scan',{detail:scan,cancelable:true});if(!window.dispatchEvent(event)){setPaletteOpen(false);return}setPartScan({barcode,nonce:Date.now()});setPage('inventory');setPaletteOpen(false);return}let scan=analyzeScan(raw),decodeError='';if(scan.length>=40||scan.byteLength>=20)try{const registration=await api.zebra.decodeRegistration({raw:scan.raw,hex:scan.sdk?.hex||''});scan={...scan,registration,vin:registration.form.vin||scan.vin,kind:'DOWÓD REJ.'}}catch(error){decodeError=error.message||String(error)}api.zebra?.recordCapture?.({...scan,decodeError}).catch(()=>{});if(scan.registration?.ok||scan.vin){setGlobalScanNotice('');openIntakeFromScan(scan);return}setGlobalScanNotice(`Nie rozpoznano kodu. ${decodeError}`);setTimeout(()=>setGlobalScanNotice(''),7000)},[openIntakeFromScan])
 const openManualForOrder=order=>{setManualContext(order?{plate:order.plate,vin:order.vin,make:order.make,model:order.model,generation:order.generation,year:order.year,engine:order.engine,power_hp:order.power_hp,engine_code:order.engine_code,gearbox_code:order.gearbox_code}:null);setPage('manual');setPaletteOpen(false)}
 useEffect(()=>{const onKey=e=>{if((e.ctrlKey||e.metaKey)&&String(e.key).toLowerCase()==='k'){e.preventDefault();setPaletteOpen(x=>!x)}else if(e.key==='Escape')setPaletteOpen(false)};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[])
 useEffect(()=>{const timer=setTimeout(()=>setBooting(false),1000);return()=>clearTimeout(timer)},[])
 useEffect(()=>createKeyboardWedge({onScan:handleGlobalScan,timeout:100,minLength:8,captureEditable:true}),[handleGlobalScan])
 useEffect(()=>{const cleanup=api?.sync?.onChanged?.(()=>{setRefresh(x=>x+1);setSyncPulse(Date.now())});return typeof cleanup==='function'?cleanup:undefined},[])
 useEffect(()=>{let alive=true;const load=()=>api.notifications.list().then(rows=>alive&&setAttentionCount(rows.length)).catch(()=>{});load();const timer=setInterval(load,30000);return()=>{alive=false;clearInterval(timer)}},[refresh])
 useEffect(()=>{const show=data=>{setRemoteNotice(data);setRefresh(x=>x+1);setTimeout(()=>setRemoteNotice(x=>x?.approvalId===data?.approvalId?null:x),9000)};const c1=api?.cloudSync?.onRemoteApproval?.(show);const c2=api?.cloudSync?.onRemoteApprovalOpen?.(data=>{show(data);openOrder(data.orderId)});return()=>{if(typeof c1==='function')c1();if(typeof c2==='function')c2()}},[])
 useEffect(()=>{const show=event=>setAppNotices(queue=>[event.detail,...queue].slice(0,5));window.addEventListener('autologika:feedback',show);return()=>window.removeEventListener('autologika:feedback',show)},[])
 useEffect(()=>{if(!appNotice)return;const timer=setTimeout(()=>setAppNotices(queue=>queue.slice(1)),appNotice.tone==='error'?8000:4500);return()=>clearTimeout(timer)},[appNotice])
 useEffect(()=>{document.documentElement.classList.toggle('workshopOutdoor',outdoorMode);localStorage.setItem('autologika.outdoorMode',outdoorMode?'1':'0')},[outdoorMode])
 const navSections=[
   ['Warsztat',[['dashboard','▦','Pulpit'],['intake','＋','Szybkie przyjęcie'],['center','◉','Centrum zlecenia'],['schedule','▥','Terminarz 2.0'],['kanban','▤','Workflow'],['live','◉','Workshop LIVE']]],
   ['Obsługa',[['notifications','!','Do uwagi'],['orders','◫','Zlecenia'],['customers','◎','Klienci / auta'],['inventory','▧','Części / magazyn'],['debtors','₿','Należności']]],
   ['Technika',[['scanner','⌗','VIN / AZTEC'],['manual','◫','Dokumentacja techniczna'],['diagnostics','⌁','Diagnostyka'],['templates','≡','Szablony prac'],['knowledge','◇','Baza wiedzy'],['assistant','✦','Asystent wiedzy']]],
   ['Firma',[['employees','♙','Pracownicy'],['reminders','◷','Autologika Care'],['finance','◈','Finanse / KPI'],['pricing','₿','Cennik Autologiki'],['documents','▣','Dokumenty'],['settings','⚙','Ustawienia']]]
 ]
 const changed=()=>setRefresh(x=>x+1)
 const primaryNav=new Set(['dashboard','intake','center','schedule','notifications','orders','customers','inventory','diagnostics','documents'])
 const visibleNavSections=navSections.map(([section,items])=>[section,items.filter(([id])=>navExpanded||primaryNav.has(id))]).filter(([,items])=>items.length)
 return <>{booting&&<BootSplash/>}{appNotice&&<FeedbackToast key={appNotice.id} notice={appNotice} close={()=>setAppNotices(queue=>queue.slice(1))}/>} {globalScanNotice&&<div className="globalScanToast"><b>Nie udało się odczytać skanu</b><span>{globalScanNotice}</span></div>}{remoteNotice&&<div className={'remoteDecisionToast '+(remoteNotice.tone||({APPROVED:'approved',DECLINED:'declined'}[remoteNotice.status]||'warning'))} role="button" tabIndex={0} onKeyDown={keyboardActivate(()=>openOrder(remoteNotice.orderId))} onClick={()=>openOrder(remoteNotice.orderId)}><span>{remoteNotice.icon||({APPROVED:'✓',DECLINED:'×',EXPIRED:'!'}[remoteNotice.status]||'↻')}</span><div><b>{remoteNotice.toastTitle||({APPROVED:'Klient zaakceptował kosztorys',DECLINED:'Klient odrzucił kosztorys',EXPIRED:'Link akceptacyjny wygasł',SUPERSEDED:'Link akceptacyjny został zastąpiony'}[remoteNotice.status]||'Zmieniono stan akceptacji')}</b><small>{[remoteNotice.customer,remoteNotice.vehicle,remoteNotice.plate].filter(Boolean).join(' · ')||`Zlecenie #${remoteNotice.orderId}`}</small><small>{money(remoteNotice.amount||0)} · {new Date(remoteNotice.decidedAt||Date.now()).toLocaleString('pl-PL')}</small>{remoteNotice.note&&<small className="remoteDecisionNote">{remoteNotice.note}</small>}</div><button onClick={e=>{e.stopPropagation();setRemoteNotice(null)}}>×</button></div>}<div className="shell"><aside><div className="brand"><img className="brandLogo" src="./brand/autologika-logo.png" alt="AutoLogika"/><div><span>WORKSHOP OPERATING SYSTEM</span></div></div><nav>{visibleNavSections.map(([section,items])=><div className="navSection" key={section}><small>{section}</small>{items.map(([id,ico,name])=><button key={id} className={page===id?'active':''} aria-current={page===id?'page':undefined} title={name} onClick={()=>setPage(id)}><span><Icon name={id}/></span><em>{name}</em>{id==='notifications'&&attentionCount>0?<i className="navCount">{attentionCount>99?'99+':attentionCount}</i>:null}</button>)}</div>)}</nav><div className="sidefoot"><div className="sideModeButtons"><button type="button" className={outdoorMode?'active':''} onClick={()=>setOutdoorMode(value=>!value)} title="Większy kontrast i elementy dotykowe">◐ Tryb warsztatowy</button><button type="button" onClick={()=>setNavExpanded(value=>{const next=!value;localStorage.setItem('autologika.navExpanded',next?'1':'0');return next})}>{navExpanded?'− Mniej modułów':'+ Wszystkie moduły'}</button></div><span className="statusDot"/>Pracujesz lokalnie<div><AppVersion/></div></div></aside><main><Top page={page} openPalette={()=>setPaletteOpen(true)} attentionCount={attentionCount} openAttention={()=>setPage('notifications')}/><div className="pageBody" key={page}>{page==='dashboard'&&<WorkshopDashboard refresh={refresh} api={api} go={setPage} openOrder={openOrder} scanDocument={openDeliveryImport}/>} {page==='intake'&&<Deferred><QuickIntake key={intakeScan?.nonce||'intake'} api={api} Panel={Panel} VehicleIntakePanel={VehicleIntakePanel} initialScan={intakeScan} changed={changed} openOrder={openOrder}/></Deferred>} {page==='notifications'&&<Notifications refreshToken={refresh} changed={changed} openOrder={openOrder}/>} {page==='debtors'&&<Debtors refreshToken={refresh} openOrder={openOrder}/>} {page==='center'&&<OrderCenter changed={changed} refreshToken={refresh} initialId={selectedOrderId} openManual={openManualForOrder} openIntake={()=>setPage('intake')}/>} {page==='schedule'&&<Deferred><WorkshopSchedule api={api} refresh={refresh} changed={changed} openOrder={openOrder}/></Deferred>} {page==='kanban'&&<Deferred><Kanban refresh={refresh} api={api} statuses={statuses} labels={labels} money={money} changed={changed} openOrder={openOrder}/></Deferred>} {page==='live'&&<Deferred><WorkshopLive refresh={refresh} api={api} labels={labels} openOrder={openOrder}/></Deferred>} {page==='orders'&&<Orders refreshToken={refresh} changed={changed} openOrder={openOrder}/>} {page==='customers'&&<Customers refreshToken={refresh} openOrder={openOrder} initialCustomer={customerTarget} initialVehicle={vehicleTarget}/>} {page==='scanner'&&<Deferred><VinScanner api={api} Panel={Panel} Empty={Empty} onUseScan={openIntakeFromScan}/></Deferred>} {page==='manual'&&<Deferred><TechnicalManual context={manualContext} onClearContext={()=>setManualContext(null)}/></Deferred>} {page==='diagnostics'&&<Deferred><Diagnostics refresh={refresh} api={api} Panel={Panel} DiagnosisEditor={DiagnosisEditor}/></Deferred>} {page==='templates'&&<Deferred><ProcedureTemplates api={api} money={money} Modal={Modal}/></Deferred>} {page==='knowledge'&&<Deferred><Knowledge refresh={refresh} api={api} Modal={Modal}/></Deferred>} {page==='assistant'&&<Deferred><AssistantKnowledge api={api} Panel={Panel} Empty={Empty}/></Deferred>} {page==='inventory'&&<Deferred><PartsWorkspace refresh={refresh} api={api} initialScan={partScan} OrdersView={Inventory} scanDocument={openDeliveryImport}/></Deferred>} {page==='employees'&&<Deferred><Employees api={api} Card={Card} money={money} durText={durText} Panel={Panel} Empty={Empty} Modal={Modal}/></Deferred>} {page==='reminders'&&<Deferred><Care refresh={refresh} api={api} openOrder={openOrder} openVehicle={openVehicle} Panel={Panel} Empty={Empty} Modal={Modal}/></Deferred>} {page==='finance'&&<Deferred><Finance refresh={refresh} api={api} money={money} Loading={Loading} Modal={Modal} Empty={Empty}/></Deferred>} {page==='pricing'&&<Deferred><CatalogPricingV2 api={api}/></Deferred>} {page==='documents'&&<Deferred><Documents api={api} Panel={Panel} Loading={Loading}/></Deferred>} {page==='settings'&&<Deferred><Settings api={api} Panel={Panel} money={money} fileSize={fileSize}/></Deferred>}</div></main></div>{showDeliveryImport&&<Deferred><DeliveryDocumentImport api={api} close={()=>setShowDeliveryImport(false)} onImported={()=>{setPage('inventory');changed()}}/></Deferred>}{paletteOpen&&<CommandPalette close={()=>setPaletteOpen(false)} go={setPage} openOrder={openOrder} openCustomer={openCustomer} openVehicle={openVehicle}/>}</>
}
