 const deferredQuery=useDebouncedValue(query),stats=useMemo(()=>attentionStats(rows),[rows]),visible=useMemo(()=>filterAttention(rows,{group,query:deferredQuery}),[rows,group,deferredQuery]),filters=[['ALL','Wszystkie',stats.total],['WAITING','Oczekiwanie',stats.WAITING],['CONTACT','Kontakt',stats.CONTACT],['PARTS','Części',stats.PARTS],['DECISIONS','Decyzje',stats.DECISIONS],['VEHICLE','Pojazdy',stats.VEHICLE]]
 if(busy&&!updated)return <Loading label="Buduję listę priorytetów" detail="Łączę oczekiwanie, kontakt, części i decyzje klientów."/>
